#include <string.h>

typedef long long ll;

typedef struct {
    int r, c;
} Node;

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    char **S = (char **)malloc(sizeof(char *) * H);
    for (int i = 0; i < H; i++) {
        S[i] = (char *)malloc(W + 1);
        scanf("%s", S[i]);
    }

    int **vis = (int **)malloc(sizeof(int *) * H);
    for (int i = 0; i < H; i++) {
        vis[i] = (int *)calloc(W, sizeof(int));
    }

    Node *queue = (Node *)malloc(sizeof(Node) * H * W);
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    ll ans = 0;

    for (int sr = 0; sr < H; sr++) {
        for (int sc = 0; sc < W; sc++) {
            if (vis[sr][sc]) continue;

            int head = 0, tail = 0;
            queue[tail++] = (Node){sr, sc};
            vis[sr][sc] = 1;

            ll black = 0, white = 0;

            while (head < tail) {
                Node cur = queue[head++];
                if (S[cur.r][cur.c] == '#') black++;
                else white++;

                for (int k = 0; k < 4; k++) {
                    int nr = cur.r + dr[k];
                    int nc = cur.c + dc[k];
                    if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                    if (vis[nr][nc]) continue;
                    if (S[nr][nc] == S[cur.r][cur.c]) continue; // only alternate colors

                    vis[nr][nc] = 1;
                    queue[tail++] = (Node){nr, nc};
                }
            }

            ans += black * white;
        }
    }

    printf("%lld\n", ans);

    for (int i = 0; i < H; i++) {
        free(S[i]);
        free(vis[i]);
    }
    free(S);
    free(vis);
    free(queue);

    return 0;
}

