    for (int i = 0; i < H; i++) {
        cin >> grid[i];
    }

    // Directions: up, down, left, right
    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};

    vector<vector<int>> component(H, vector<int>(W, -1));
    vector<int> comp_black, comp_white; // counts per component

    int comp_id = 0;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (component[i][j] != -1) continue;

            // BFS/DFS to find component
            queue<pair<int,int>> q;
            q.push({i, j});
            component[i][j] = comp_id;
            int black_cnt = 0, white_cnt = 0;

            if (grid[i][j] == '#') black_cnt++;
            else white_cnt++;

            while (!q.empty()) {
                auto [x, y] = q.front();
                q.pop();
                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d];
                    int ny = y + dy[d];
                    if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
                    if (component[nx][ny] != -1) continue;
                    // Only move to opposite color
                    if (grid[nx][ny] == grid[x][y]) continue;
                    component[nx][ny] = comp_id;
                    if (grid[nx][ny] == '#') black_cnt++;
                    else white_cnt++;
                    q.push({nx, ny});
                }
            }
            comp_black.push_back(black_cnt);
            comp_white.push_back(white_cnt);
            comp_id++;
        }
    }

    long long ans = 0;
    for (int c = 0; c < comp_id; c++) {
        ans += 1LL * comp_black[c] * comp_white[c];
    }

    cout << ans << "\n";

    return 0;
}

