        for j in range(W):
            if visited[i][j]:
                continue

            # Explore a connected component in the graph where
            # edges exist only between adjacent cells of different colors.
            q = deque()
            q.append((i, j))
            visited[i][j] = True

            black = 0
            white = 0

            while q:
                x, y = q.popleft()
                if S[x][y] == '#':
                    black += 1
                else:
                    white += 1

                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny]:
                        if S[nx][ny] != S[x][y]:
                            visited[nx][ny] = True
                            q.append((nx, ny))

            ans += black * white

